-- Biodata upload is stopped: every profile is built by asking questions. Prompt rules 9 and 10, only where
-- they still hold the default text, so admin edits are kept. The unused biodata messages are left in place.
UPDATE "settings" SET "value" = to_jsonb(replace("value" #>> '{}', '9. শুরুতে সিস্টেম জিজ্ঞেস করে, তৈরি বায়োডাটা আছে কিনা। "না" বা তৈরি নেই বললে get_next_question দিয়ে প্রশ্ন শুরু করো। আছে বললে সেটির ছবি বা PDF এখানে পাঠাতে বলো (চাইলে লিখেও পাঠাতে পারেন)।', '9. Every profile is built by asking questions. Right after consent the system asks the first question; ask the rest with get_next_question. We do not take a ready-made biodata: if someone offers one or says they will send it, thank them and say a few short questions are all we need.')) WHERE "key" = 'system_prompt' AND position('9. শুরুতে সিস্টেম জিজ্ঞেস করে, তৈরি বায়োডাটা আছে কিনা। "না" বা তৈরি নেই বললে get_next_question দিয়ে প্রশ্ন শুরু করো। আছে বললে সেটির ছবি বা PDF এখানে পাঠাতে বলো (চাইলে লিখেও পাঠাতে পারেন)।' in "value" #>> '{}') > 0;
--> statement-breakpoint
UPDATE "settings" SET "value" = to_jsonb(replace("value" #>> '{}', '10. "[বায়োডাটা]" দিয়ে শুরু হওয়া বার্তা ব্যবহারকারীর পাঠানো বায়োডাটার ছবি বা PDF থেকে পড়া লেখা। এখান থেকে questions তালিকার যত উত্তর পাওয়া যায় সব save_answer দিয়ে (source=volunteered) আর পাত্র/পাত্রীর চাহিদা save_preference দিয়ে সংরক্ষণ করো; লেখা অস্পষ্ট হলে confidence 0.8-এর কম দাও। তারপর ছোট করে জানাও কোন তথ্যগুলো পেয়েছ, আর get_next_question দিয়ে বাকি প্রশ্ন করো।', '10. Images are taken only as profile photos. A file (PDF, Word) is not read; the system tells the user so.')) WHERE "key" = 'system_prompt' AND position('10. "[বায়োডাটা]" দিয়ে শুরু হওয়া বার্তা ব্যবহারকারীর পাঠানো বায়োডাটার ছবি বা PDF থেকে পড়া লেখা। এখান থেকে questions তালিকার যত উত্তর পাওয়া যায় সব save_answer দিয়ে (source=volunteered) আর পাত্র/পাত্রীর চাহিদা save_preference দিয়ে সংরক্ষণ করো; লেখা অস্পষ্ট হলে confidence 0.8-এর কম দাও। তারপর ছোট করে জানাও কোন তথ্যগুলো পেয়েছ, আর get_next_question দিয়ে বাকি প্রশ্ন করো।' in "value" #>> '{}') > 0;
